// Ubah kartu produk mentah dari bookmarklet jadi permintaan ekstraksi ke Claude.
let body = $input.first().json.body;
if (typeof body === 'string') { try { body = JSON.parse(body); } catch (e) { body = {}; } }
const cards = (body && body.cards) || [];
if (!cards.length) return [];
const list = cards.map((c, i) => `#${i}\nlink: ${c.h}\n${c.t}`).join('\n---\n');
const requestBody = {
  model: 'claude-haiku-4-5-20251001',
  max_tokens: 16000,
  messages: [{ role: 'user', content:
    'Ini kartu produk dari dasbor Shopee Affiliate. Ubah tiap kartu jadi JSON. Balas HANYA array JSON tanpa teks lain: ' +
    '[{"i":nomor,"name":"nama produk","shop":"nama toko atau kosong","price":harga_rupiah_angka,"sales":total_terjual_angka,' +
    '"rate":persen_komisi_desimal_mis_0.1,"rating":angka_atau_0}]. ' +
    'Konversi "1,2RB+" jadi 1200, "10RB" jadi 10000, "1JT" jadi 1000000. Kalau ada rentang harga pakai yang terendah.\n\n' + list }],
};
return [{ json: { requestBody, cards } }];

// Simpan snapshot hari ini (static data workflow, 30 hari terakhir) lalu ranking 1d/3d/7d.
// Logika murni: tanda tangan API, hitung tren dari snapshot, skor "worth it" untuk konten affiliate.

// Shopee Affiliate Open API: Signature = SHA256(appId + timestamp + payload + secret)
function signHeader(appId, secret, payload, ts = Math.floor(Date.now() / 1000)) {
  const sig = require('crypto').createHash('sha256').update(`${appId}${ts}${payload}${secret}`).digest('hex');
  return `SHA256 Credential=${appId}, Timestamp=${ts}, Signature=${sig}`;
}

const num = (v) => Number(v) || 0;

// Ubah node productOfferV2 jadi baris snapshot ringkas.
function toRow(n) {
  return {
    id: String(n.itemId),
    name: n.productName,
    shop: n.shopName,
    price: num(n.priceMin),
    sales: num(n.sales), // kumulatif dari Shopee
    rate: num(n.commissionRate), // 0.1 = 10%
    rating: num(n.ratingStar),
    link: n.offerLink || n.productLink,
    image: n.imageUrl,
  };
}

// snapshots: [{ date: 'YYYY-MM-DD', items: [row] }] urut lama → baru.
// Penjualan per periode = sales hari ini − sales N hari lalu (pakai snapshot terdekat yang ada).
function trend(snapshots, days) {
  const latest = snapshots[snapshots.length - 1];
  const target = new Date(latest.date);
  target.setUTCDate(target.getUTCDate() - days);
  const base = [...snapshots].reverse().find((s) => new Date(s.date) <= target)
    || (snapshots.length > 1 ? snapshots[0] : null);
  const prev = new Map((base ? base.items : []).map((r) => [r.id, r]));
  const span = base ? Math.max(1, (new Date(latest.date) - new Date(base.date)) / 864e5) : 0;

  return latest.items.map((r) => {
    const p = prev.get(r.id);
    const sold = p ? Math.max(0, r.sales - p.sales) : null; // null = belum ada data pembanding
    const commission = r.price * r.rate;
    const growth = p && p.sales > 0 ? sold / p.sales : null;
    return {
      ...r,
      sold,
      perDay: sold === null ? null : sold / span,
      commission,
      potential: sold === null ? null : sold * commission, // estimasi omzet komisi pasar periode ini
      growth,
      baseDate: base ? base.date : null,
    };
  });
}

// Skor 0-100: potensi komisi (45%), momentum penjualan (25%), komisi/klik (15%), rating (10%), harga ramah impuls (5%).
function score(rows) {
  const has = rows.filter((r) => r.sold !== null);
  const pool = has.length ? has : rows;
  const logNorm = (key) => {
    const max = Math.max(...pool.map((r) => Math.log1p(num(r[key]))), 1e-9);
    return (r) => Math.log1p(num(r[key])) / max;
  };
  const nPot = logNorm(has.length ? 'potential' : 'sales');
  const nMom = logNorm(has.length ? 'perDay' : 'sales');
  const nCom = logNorm('commission');
  const priceFit = (p) => (p <= 0 ? 0 : p <= 150000 ? 1 : Math.max(0, 1 - Math.log10(p / 150000)));

  return pool
    .map((r) => {
      const s = 0.45 * nPot(r) + 0.25 * nMom(r) + 0.15 * nCom(r) + 0.1 * Math.max(0, (r.rating - 4) / 1) + 0.05 * priceFit(r.price);
      return { ...r, score: Math.round(s * 1000) / 10, reason: reason(r) };
    })
    .sort((a, b) => b.score - a.score);
}

function reason(r) {
  const out = [];
  if (r.sold !== null) out.push(`terjual ${fmt(r.sold)} (${fmt(Math.round(r.perDay))}/hari)`);
  out.push(`komisi ${(r.rate * 100).toFixed(1)}% ≈ Rp${fmt(Math.round(r.commission))}/order`);
  if (r.growth !== null && r.growth >= 0.1) out.push(`naik ${(r.growth * 100).toFixed(0)}%`);
  if (r.rating >= 4.8) out.push(`rating ${r.rating}`);
  return out.join(' · ');
}

const fmt = (n) => Math.round(num(n)).toLocaleString('id-ID');

function report(snapshots, periods = [1, 3, 7], top = 10) {
  const latest = snapshots[snapshots.length - 1];
  const out = { date: latest.date, periods: {} };
  for (const d of periods) out.periods[`${d}d`] = score(trend(snapshots, d)).slice(0, top);
  return out;
}

function toText(rep) {
  const lines = [`🔥 Produk Trending Shopee — ${rep.date}`];
  for (const [k, rows] of Object.entries(rep.periods)) {
    const noBase = rows.length && rows[0].sold === null;
    lines.push('', `== ${k}${noBase ? ' (belum ada snapshot pembanding, pakai total terjual)' : ''} ==`);
    rows.forEach((r, i) => {
      lines.push(`${i + 1}. [${r.score}] ${r.name} — Rp${fmt(r.price)}`, `   ${r.reason}`);
      if (r.potential) lines.push(`   potensi komisi pasar: Rp${fmt(r.potential)}`);
      lines.push(`   ${r.link}`);
    });
  }
  return lines.join('\n');
}


const { cards } = $('Siapkan Ekstraksi').first().json;
const res = $input.first().json;
const raw = (res.content && res.content[0] && res.content[0].text) || '[]';
let parsed = [];
try { parsed = JSON.parse(raw.slice(raw.indexOf('['), raw.lastIndexOf(']') + 1)); } catch (e) {}
const items = parsed.map((p) => {
  const c = cards[p.i] || {};
  const m = (c.h || '').match(/-i\.(\d+)\.(\d+)|product\/(\d+)\/(\d+)|itemId=(\d+)/);
  const id = m ? (m[2] || m[4] || m[5]) : String(p.name || '').toLowerCase().slice(0, 80);
  return { id, name: p.name, shop: p.shop || '', price: Number(p.price) || 0, sales: Number(p.sales) || 0,
    rate: Number(p.rate) > 1 ? Number(p.rate) / 100 : Number(p.rate) || 0, rating: Number(p.rating) || 0, link: c.h, image: c.img };
}).filter((r) => r.id && r.name);
if (!items.length) return [{ json: { text: '⚠️ Shopee Trending: produk gagal dibaca dari halaman. Coba scroll daftar produk dulu lalu klik bookmark lagi.', ideas: null } }];

const store = $getWorkflowStaticData('global');
const date = new Date(Date.now() + 7 * 36e5).toISOString().slice(0, 10);
const snaps = (store.snapshots || []).filter((s) => s.date !== date);
const prev = (store.snapshots || []).find((s) => s.date === date);
const merged = new Map((prev ? prev.items : []).map((r) => [r.id, r]));
for (const r of items) merged.set(r.id, r); // klik berkali-kali di hari yang sama = digabung
snaps.push({ date, items: [...merged.values()] });
store.snapshots = snaps.slice(-30);

const rep = report(store.snapshots, [1, 3, 7], 10);
const best = Object.values(rep.periods).pop().slice(0, 5).map((r) => `- ${r.name} (Rp${r.price}, ${r.reason})`).join('\n');
const ideas = {
  model: 'claude-haiku-4-5-20251001', max_tokens: 1200,
  messages: [{ role: 'user', content: 'Kamu strategist konten affiliate Shopee (TikTok/Reels/Shopee Video). Untuk tiap produk berikut beri 1 baris hook + 1 baris angle konten, singkat, bahasa Indonesia santai, tanpa markdown:\n' + best }],
};
return [{ json: { text: toText(rep) + `\n\n(${merged.size} produk tersimpan hari ini, riwayat ${store.snapshots.length} hari)`, ideas } }];

const base = $('Simpan & Ranking').first().json.text;
const r = $input.first().json;
const ideas = r.content && r.content[0] ? '\n\n💡 Ide konten (top 5):\n' + r.content[0].text : '';
const text = base + ideas;
const parts = [];
for (let i = 0; i < text.length; i += 4000) parts.push({ json: { text: text.slice(i, i + 4000) } });
return parts;
